"""Camera-guided dual-bottle episode. Live commands are recorded for replay."""
import sys,json,pathlib,numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot, EpisodeOver
OUT=pathlib.Path('/app/output')
CAMS=('head_camera','front_camera','left_camera','right_camera','observer_camera')
r=Robot()
seq=0

def run(cmd):
 global seq
 seq+=1
 if cmd['type']=='observe':
  res=r.get_obs(cameras=CAMS,include_depth=True,seconds=cmd.get('seconds',0))
 else:
  res=r.submit(cmd['type'],cmd['actions'],dt=cmd.get('dt',.05),cameras=CAMS,include_depth=True,video='both',note=cmd.get('note',''))
 res.save(str(OUT/f'run{seq:02d}'))
 print(json.dumps({'run':seq,'meta':{k:v for k,v in res.meta.items() if k not in ('cameras','proprio')},'now':res.meta.get('proprio',{}).get('now')}),flush=True)
 return res.done

if '--live' in sys.argv:
 for line in sys.stdin:
  try:
   cmd=json.loads(line)
   with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps(cmd)+'\n')
   if run(cmd):break
  except EpisodeOver as e:
   print('EpisodeOver: '+str(e),flush=True);break
  except Exception as e:print(type(e).__name__+': '+str(e),flush=True)
else:
 for line in (OUT/'actions.jsonl').read_text().splitlines():
  if run(json.loads(line)):break
PY
python /app/output/gen.py --live

